    transparent,
    var(--color-primary),
    transparent
  );
}

.heroContent {
  max-w-3xl text-center z-10;
}

.heroEyebrow {
  @apply text-xs font-bold tracking-widest uppercase mb-6;
  color: var(--color-primary);
  letter-spacing: 0.15em;
}

.heroTitle {
  @apply text-6xl md:text-7xl font-black mb-8 leading-tight;
  background: linear-gradient(
    135deg,
    var(--color-primary),
    var(--color-secondary)
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  text-fill-color: transparent;
  animation: fadeInDown 0.8s ease-out;
}

.heroSubtitle {
  @apply text-lg md:text-xl leading-relaxed mb-12;
  color: var(--color-body);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
  animation: fadeInUp 0.8s ease-out 0.2s both;
}

.ctaGroup {
  @apply flex flex-col sm:flex-row gap-6 justify-center items-center;
  animation: fadeInUp 0.8s ease-out 0.4s both;
}

.ctaGroup > :first-child {
  /* Styles the primary button (uses global .btn class) */
  @apply px-8 py-4 text-lg;
}

.secondaryLink {
  @apply text-body hover:text-heading transition-colors underline underline-offset-4;
  font-weight: 500;
}

.secondaryLink:hover {
  color: var(--color-primary);
}

/* Briefing Section */
.briefingSection {
  @apply px-4 py-24;
  background: var(--color-dark);
  border-top: 1px solid var(--color-lighter);
}

.sectionTitle {
  @apply text-3xl md:text-4xl font-bold text-center mb-16;
  color: var(--color-heading);
}

.briefingGrid {
  @apply grid md:grid-cols-3 gap-6 max-w-6xl mx-auto;
}

.briefingCard {
  @apply p-6 rounded-xl border transition-all duration-300;
  background: var(--color-light);
  border-color: var(--color-lighter);
  position: relative;
  overflow: hidden;
}

.briefingCard::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-primary),
    transparent
  );
}

.briefingCard:hover {
  border-color: var(--color-primary);
  background: linear-gradient(
    135deg,
    var(--color-light),
    color-mix(in srgb, var(--color-primary) 5%, var(--color-light))
  );
  transform: translateY(-4px);
}

.cardCode {
  @apply text-xs font-bold tracking-widest uppercase mb-3;
  color: var(--color-primary);
  letter-spacing: 0.1em;
}

.cardTitle {
  @apply text-xl font-bold mb-3;
  color: var(--color-heading);
}

.cardDescription {
  @apply text-sm leading-relaxed;
  color: var(--color-body);
  line-height: 1.6;
}

/* Trust Section */
.trustSection {
  @apply px-4 py-16;
  background: var(--color-light);
  border-top: 1px solid var(--color-lighter);
  text-align: center;
}

.trustText {
  @apply text-body text-sm md:text-base max-w-2xl mx-auto;
  font-weight: 500;
  letter-spacing: 0.5px;
}

/* Animations */
@keyframes fadeInDown {
  from {
    opacity: 0;
    transform: translateY(-20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .heroTitle {
    @apply text-4xl;
  }

  .heroSubtitle {
    @apply text-base;
  }

  .sectionTitle {
    @apply text-2xl;
  }

  .briefingCard {
    @apply p-5;
  }

  .cardTitle {
    @apply text-lg;
  }
}
